// Generated by philote from page /projects/[id]. PageBody's body is written by
// a model and pinned in philote.lock (decision-2).
/* eslint-disable @typescript-eslint/no-unused-vars -- every page gets the same imports */
import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { connection } from "next/server";
import { Suspense } from "react";

import * as Icons from "lucide-react";

import { projects } from "@/lib/api";
import { readProjectView } from "@/lib/reads";
import { cn } from "@/lib/utils";

import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";

import ProjectView from "@/components/common/project-view";

export const metadata: Metadata = { title: "Project" };

export default function Page({ params }: PageProps<"/projects/[id]">) {
    return (
        <main className="flex flex-1 flex-col">
            <PageBody
                title={"Project"}
                content={(className) => (
                    <div className={className}>
                        <Suspense fallback={<p className="text-muted-foreground">Loading…</p>}>
                            <Record params={params} />
                        </Suspense>
                    </div>
                )}
            />
        </main>
    );
}

// Record streams in after the page's shell, so a missing record renders
// not-found.tsx with noindex, but the response status stays 200.
async function Record({ params }: Pick<PageProps<"/projects/[id]">, "params">) {
    await connection();
    const { id } = await params;
    const result = await projects.get(id);
    if (!result.ok) {
        notFound();
    }
    const item = await readProjectView(result.value);
    return <ProjectView {...item} />;
}

type PageBodyProps = {
    title: string;
    content: (className: string) => React.ReactNode;
};

function PageBody({ title, content }: PageBodyProps): React.ReactNode {
    return (
        <div className="mx-auto flex w-full max-w-3xl flex-col gap-4 px-4 py-6 sm:px-6 sm:py-8 lg:py-10">
            <div className="flex items-center gap-2 text-muted-foreground">
                <Icons.FolderKanban className="size-4" aria-hidden="true" />
                <h1 className="text-xs font-medium uppercase tracking-wider">{title}</h1>
            </div>
            <Separator orientation="horizontal" />
            {content("w-full")}
        </div>
    );
}
